#!/usr/bin/env bash
# Idempotent: installs or refreshes the systemd --user units (2 services + 11
# timers, generated by scripts/install_systemd.sh, the single source of the
# schedule). Runs on every deploy; does not build or restart the app.
set -euo pipefail
cd "$(dirname "$0")/../.."

# Units point at THIS folder. Without the database it is the wrong folder, and
# init_db would boot the app on a fresh empty one where the client then writes.
if [ ! -f storage/portfolio.db ] && [ "${1:-}" != --first-install ]; then
  echo "install: sem storage/portfolio.db em $PWD (pasta errada? primeira instalação: --first-install)" >&2
  exit 1
fi
bash scripts/install_systemd.sh
